	title 'Interrupt Stuff'************************************************************************ Interrupt Record Stuff* Copyright (C) 1988* Apple Computer, Inc.* All Rights Reserved** This file contains the routines**      GetInterruptState*      SetInterruptState*      GetIntStateRecSize************************************************************************	include 'all.macros'	include 'mt.equates.asm'	include '::sys.equs.asm'IntStateRecSize	equ AVal-irq_A*****************************************************************GetInterruptState	PROC EXPORT** This copies the first BytesDesired bytes of the system interrupt* variables into the specified InterruptStateRecord.*** Inputs:*	StateRecPtr*	BytesDesired** Outputs:*	none** External Refs:	import EndCall6** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	DefineStackOrigD	wordRTL1	block 3RTL2	block 3BytesDesired	wordStateRecPtr	LONG	phd	tsc	tcd	phb	pea #$e1e1	plb	plb	ldy BytesDesired	cpy #IntStateRecSize	bcc @1	ldy #IntStateRecSize@1	dey	sep #$20	longa offLoop	lda |irq_A,y	sta [StateRecPtr],y	dey	bpl Loop	rep #$20	longa on	plb	jml EndCall6	ENDP*****************************************************************SetInterruptState	PROC EXPORT** This copies the first BytesDesired bytes from the specified * IntStateRecord into the interrupt state variables in bank $E1.*** Inputs:*	StateRecPtr*	BytesDesired** Outputs:*	none** External Refs:	import EndCall6** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	DefineStackOrigD	wordRTL1	block 3RTL2	block 3BytesDesired	wordStateRecPtr	LONG	phd	tsc	tcd	phb	pea #$e1e1	plb	plb	ldy BytesDesired	cpy #IntStateRecSize	bcc @1	ldy #IntStateRecSize@1	dey	sep #$20	longa offLoop	lda [StateRecPtr],y	sta |irq_a,y	dey	bpl Loop	rep #$20	longa on	plb	jml EndCall6	ENDP*****************************************************************GetIntStateRecSize	PROC EXPORT** This returns the size of the interrupt state record.*** Inputs:*	space for integer** Outputs:*	SizeofIntStateRecord** External Refs:	import oEndCall0** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	DefineStackRTL1	block 3RTL2	block 3Size	word	lda #IntStateRecSize	sta Size,s	jml oEndCall0	ENDP	END